CREATE OR ALTER PROCEDURE [dbo].[uspOrganizationUnit_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @CompanyId UNIQUEIDENTIFIER = NULL
	, @ParentId UNIQUEIDENTIFIER = NULL
	, @UnitType NVARCHAR(MAX) = NULL
	, @ManagerId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[CompanyId]
			, t.[ParentId]
			, t.[Code]
			, t.[Name]
			, t.[UnitType]
			, t.[ManagerId]
			, t.[Status]
			, t.[Note]
			, t.[Address]
			, t.[Phone]
			, t.[CreatedDate]
		FROM [dbo].[OrganizationUnit] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[Code] LIKE CONCAT('%', @SearchText, '%') OR t.[Name] LIKE CONCAT('%', @SearchText, '%'))
			AND (@CompanyId IS NULL OR t.[CompanyId] = @CompanyId)
			AND (@ParentId IS NULL OR t.[ParentId] = @ParentId)
			AND (ISNULL(@UnitType, '') = '' OR t.[UnitType] = @UnitType)
			AND (@ManagerId IS NULL OR t.[ManagerId] = @ManagerId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'companyId' THEN r.[CompanyId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'companyId' THEN r.[CompanyId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'parentId' THEN r.[ParentId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'parentId' THEN r.[ParentId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'code' THEN r.[Code] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'code' THEN r.[Code] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'name' THEN r.[Name] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'name' THEN r.[Name] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'unitType' THEN r.[UnitType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'unitType' THEN r.[UnitType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'managerId' THEN r.[ManagerId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'managerId' THEN r.[ManagerId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'address' THEN r.[Address] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'address' THEN r.[Address] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'phone' THEN r.[Phone] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'phone' THEN r.[Phone] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
